IF OBJECT_ID(N'dbo.TDVTSetting',N'U') IS NULL CREATE TABLE dbo.TDVTSetting(CompanyID bigint NOT NULL PRIMARY KEY,IsEnabled bit NOT NULL DEFAULT 1,DefaultOpenHours int NOT NULL DEFAULT 72,DefaultApproverUserID bigint NULL,UpdateDate datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdateBy bigint NULL);
IF OBJECT_ID(N'dbo.TDVTTopic',N'U') IS NULL CREATE TABLE dbo.TDVTTopic(VoteTopicID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,VoteNo nvarchar(40) NOT NULL,TopicName nvarchar(300) NOT NULL,Description nvarchar(2000) NULL,TargetMode nvarchar(20) NOT NULL,IdentityMode nvarchar(20) NOT NULL,StatusCode nvarchar(30) NOT NULL DEFAULT N'DRAFT',OpenDateTime datetime2 NOT NULL,CloseDateTime datetime2 NOT NULL,CreateDate datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreateBy bigint NOT NULL,UpdateDate datetime2 NULL,UpdateBy bigint NULL,SubmitDate datetime2 NULL,SubmitBy bigint NULL,ApproveDate datetime2 NULL,ApproveBy bigint NULL,PublishDate datetime2 NULL,PublishBy bigint NULL,RowVersion rowversion NOT NULL,CONSTRAINT UQ_TDVTTopic_No UNIQUE(CompanyID,VoteNo),CONSTRAINT CK_TDVTTopic_Target CHECK(TargetMode IN(N'ALL',N'CUSTOM')),CONSTRAINT CK_TDVTTopic_Identity CHECK(IdentityMode IN(N'ANONYMOUS',N'OPEN')),CONSTRAINT CK_TDVTTopic_Status CHECK(StatusCode IN(N'DRAFT',N'PENDING_APPROVAL',N'APPROVED',N'PUBLISHED',N'CLOSED',N'RETURNED')),CONSTRAINT CK_TDVTTopic_Date CHECK(OpenDateTime<CloseDateTime));
IF OBJECT_ID(N'dbo.TDVTTopicOption',N'U') IS NULL CREATE TABLE dbo.TDVTTopicOption(VoteTopicOptionID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,VoteTopicID bigint NOT NULL REFERENCES dbo.TDVTTopic(VoteTopicID) ON DELETE CASCADE,OptionText nvarchar(500) NOT NULL,SortOrder int NOT NULL,CONSTRAINT UQ_TDVTTopicOption UNIQUE(VoteTopicID,SortOrder));
IF OBJECT_ID(N'dbo.TDVTTopicTarget',N'U') IS NULL CREATE TABLE dbo.TDVTTopicTarget(VoteTopicTargetID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,VoteTopicID bigint NOT NULL REFERENCES dbo.TDVTTopic(VoteTopicID) ON DELETE CASCADE,TargetType nvarchar(20) NOT NULL,TargetID bigint NOT NULL,CONSTRAINT CK_TDVTTarget_Type CHECK(TargetType IN(N'EMPLOYEE',N'DEPARTMENT')));
IF OBJECT_ID(N'dbo.TDVTTopicVoter',N'U') IS NULL CREATE TABLE dbo.TDVTTopicVoter(VoteTopicVoterID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,VoteTopicID bigint NOT NULL REFERENCES dbo.TDVTTopic(VoteTopicID) ON DELETE CASCADE,UserID bigint NOT NULL,EmployeeID bigint NULL,VotedAt datetime2 NULL,CONSTRAINT UQ_TDVTTopicVoter UNIQUE(VoteTopicID,UserID));
IF OBJECT_ID(N'dbo.TDVTVote',N'U') IS NULL CREATE TABLE dbo.TDVTVote(VoteID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,VoteTopicID bigint NOT NULL REFERENCES dbo.TDVTTopic(VoteTopicID),VoteTopicVoterID bigint NOT NULL REFERENCES dbo.TDVTTopicVoter(VoteTopicVoterID),VoteTopicOptionID bigint NOT NULL REFERENCES dbo.TDVTTopicOption(VoteTopicOptionID),VoteDate datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_TDVTVote_Voter UNIQUE(VoteTopicVoterID));
IF OBJECT_ID(N'dbo.TDVTApprovalHistory',N'U') IS NULL CREATE TABLE dbo.TDVTApprovalHistory(VoteApprovalHistoryID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,VoteTopicID bigint NOT NULL REFERENCES dbo.TDVTTopic(VoteTopicID) ON DELETE CASCADE,ActionCode nvarchar(30) NOT NULL,Remark nvarchar(1000) NULL,ActionBy bigint NOT NULL,ActionDate datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF OBJECT_ID(N'dbo.TDVTAuditHistory',N'U') IS NULL CREATE TABLE dbo.TDVTAuditHistory(VoteAuditHistoryID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,VoteTopicID bigint NOT NULL REFERENCES dbo.TDVTTopic(VoteTopicID) ON DELETE CASCADE,ActionCode nvarchar(30) NOT NULL,Detail nvarchar(max) NULL,ActionBy bigint NOT NULL,ActionDate datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX IX_TDVTTopic_List ON dbo.TDVTTopic(CompanyID,StatusCode,OpenDateTime);
CREATE INDEX IX_TDVTTopicVoter_User ON dbo.TDVTTopicVoter(CompanyID,UserID,VoteTopicID);
UPDATE PM SET IsActive=1,UpdateDate=SYSUTCDATETIME() FROM dbo.TDADProjectMenu PM JOIN dbo.TDADProject P ON P.ProjectID=PM.ProjectID WHERE P.ProjectCode=N'LAOO_VOTE' AND PM.MenuCode IN(N'44001',N'44002',N'44003',N'44004',N'44005');
